// Parse Claude's response into structured data
const response = $input.first().json;
const claudeText = response.content[0].text;

let analysis;
try {
  // Extract JSON from Claude response (may have markdown formatting)
  const jsonMatch = claudeText.match(/\{[\s\S]*\}/);
  analysis = JSON.parse(jsonMatch[0]);
} catch (e) {
  analysis = {
    intent_score: 5,
    urgency: 'medium',
    category: 'other',
    detected_language: 'fr',
    key_topics: [],
    summary: claudeText.substring(0, 200),
    suggested_reply: ''
  };
}

// Pass through original payload
const payload = $('Code - Validate Payload').first().json;

return [{
  json: {
    ...payload,
    analysis: analysis,
    intent_score: analysis.intent_score,
    urgency: analysis.urgency,
    category: analysis.category,
    suggested_reply: analysis.suggested_reply,
    summary: analysis.summary
  }
}];

